    Map<String, String> labels = new HashMap<>();
    labels.put("group", "a");
    labels.put("job", "0");
    metricsMap.put("with_label_metric;group:a,job:0", 1L);
    labellessMetricMap.put("without_label_metric", 1L);
    metrics.registerGauges(metricsMap, Option.empty());
