@Test
void testTableNotExistsOrDoesNotMatchSpecification() {
    BigQuerySyncConfig config = new BigQuerySyncConfig(properties);
    client = new HoodieBigQuerySyncClient(config, mockBigQuery);
    // table does not exist
    assertTrue(client.tableNotExistsOrDoesNotMatchSpecification(TEST_TABLE));
    TableId tableId = TableId.of(PROJECT_ID, TEST_DATASET, TEST_TABLE);
    Table table = mock(Table.class);
    when(mockBigQuery.getTable(tableId)).thenReturn(table);
    ExternalTableDefinition externalTableDefinition = mock(ExternalTableDefinition.class);
    when(table.exists()).thenReturn(true);
    when(table.getDefinition()).thenReturn(externalTableDefinition);
    // manifest does not exist
    when(externalTableDefinition.getSourceUris()).thenReturn(Collections.emptyList());
    assertTrue(client.tableNotExistsOrDoesNotMatchSpecification(TEST_TABLE));
    // manifest exists but base path is outdated
    when(externalTableDefinition.getSourceUris()).thenReturn(Collections.singletonList(ManifestFileWriter.ABSOLUTE_PATH_MANIFEST_FOLDER_NAME));
    when(externalTableDefinition.getHivePartitioningOptions()).thenReturn(HivePartitioningOptions.newBuilder().setSourceUriPrefix(basePath + "1").build());
    assertTrue(client.tableNotExistsOrDoesNotMatchSpecification(TEST_TABLE));
    // manifest exists, base path is up-to-date
    when(externalTableDefinition.getHivePartitioningOptions()).thenReturn(HivePartitioningOptions.newBuilder().setSourceUriPrefix(basePath + "/").build());
    assertFalse(client.tableNotExistsOrDoesNotMatchSpecification(TEST_TABLE));
}

@Test
public void testSkipCorruptedCheck() throws Exception {
    // normal case: if the block is corrupted, we should be able to read back a corrupted block
    Reader reader1 = createCorruptedFile("test-fileid1");
    HoodieLogBlock block = reader1.next();
    assertEquals(HoodieLogBlockType.CORRUPT_BLOCK, block.getBlockType(), "The read block should be a corrupt block");
    reader1.close();
    // as we can't mock a private method or directly test it, we are going this route.
    // So adding a corrupted block which ideally should have been skipped for write transactional system. and hence when we call next() on log block reader, it will fail.
    Reader reader2 = createCorruptedFile("test-fileid2");
    assertTrue(reader2.hasNext(), "We should have corrupted block next");
    // mock the fs to be GCS to skip isBlockCorrupted() check
    Field f1 = reader2.getClass().getDeclaredField("storage");
    f1.setAccessible(true);
    HoodieStorage mockStorage = Mockito.mock(HoodieStorage.class);
    when(mockStorage.getScheme()).thenReturn("gs");
    f1.set(reader2, mockStorage);
    // except an exception for block type since the block is corrupted
    Exception exception = assertThrows(IllegalArgumentException.class, reader2::next);
    assertTrue(exception.getMessage().contains("Invalid block byte type found"));
    reader2.close();
}

