    ReceivedMessage message1 = ReceivedMessage.newBuilder().setAckId("1").setMessage(PubsubMessage.newBuilder().setMessageId("msgId1").build()).build();
    ReceivedMessage message2 = ReceivedMessage.newBuilder().setAckId("2").setMessage(PubsubMessage.newBuilder().setMessageId("msgId2").build()).build();
    ReceivedMessage message3 = ReceivedMessage.newBuilder().setAckId("3").setMessage(PubsubMessage.newBuilder().setMessageId("msgId3").build()).build();
    when(mockPubsubQueueClient.makePullRequest(mockSubscriber, SUBSCRIPTION_NAME, SMALL_BATCH_SIZE)).thenReturn(PullResponse.newBuilder().addReceivedMessages(message1).build()).thenReturn(PullResponse.newBuilder().addReceivedMessages(message2).build()).thenReturn(PullResponse.newBuilder().addReceivedMessages(message3).build());
    PubsubMessagesFetcher fetcher = new PubsubMessagesFetcher(PROJECT_ID, SUBSCRIPTION_ID, SMALL_BATCH_SIZE, MAX_MESSAGES_IN_REQUEST, MAX_WAIT_TIME_IN_REQUEST, mockPubsubQueueClient);
