private void setMockQueryRunner(Dataset<Row> inputDs, Option<String> nextCheckPointOpt) {
    when(mockQueryRunner.run(Mockito.any(QueryInfo.class), Mockito.any())).thenAnswer(invocation -> {
        QueryInfo queryInfo = invocation.getArgument(0);
        QueryInfo updatedQueryInfo = nextCheckPointOpt.map(nextCheckPoint -> queryInfo.withUpdatedEndInstant(nextCheckPoint)).orElse(queryInfo);
        if (updatedQueryInfo.isSnapshot()) {
            return Pair.of(updatedQueryInfo, inputDs.filter(String.format("%s >= '%s'", HoodieRecord.COMMIT_TIME_METADATA_FIELD, updatedQueryInfo.getStartInstant())).filter(String.format("%s <= '%s'", HoodieRecord.COMMIT_TIME_METADATA_FIELD, updatedQueryInfo.getEndInstant())));
        }
        return Pair.of(updatedQueryInfo, inputDs);
    });
}

