@Test
public void testGetErrorTableWriter() {
    SparkSession sparkSession = Mockito.mock(SparkSession.class);
    HoodieSparkEngineContext sparkContext = Mockito.mock(HoodieSparkEngineContext.class);
    FileSystem fileSystem = Mockito.mock(FileSystem.class);
    TypedProperties props = new TypedProperties();
    // No error table writer config
    assertThrows(IllegalArgumentException.class, () -> ErrorTableUtils.getErrorTableWriter(new HoodieStreamer.Config(), sparkSession, props, sparkContext, fileSystem));
    // Empty error table writer config
    props.put("hoodie.errortable.write.class", StringUtils.EMPTY_STRING);
    assertThrows(IllegalStateException.class, () -> ErrorTableUtils.getErrorTableWriter(new HoodieStreamer.Config(), sparkSession, props, sparkContext, fileSystem));
    // Proper error table writer config
    props.put("hoodie.errortable.write.class", TestErrorTable.class.getName());
    assertTrue(ErrorTableUtils.getErrorTableWriter(new HoodieStreamer.Config(), sparkSession, props, sparkContext, fileSystem).get() instanceof TestErrorTable);
    // Wrong error table writer config
    props.put("hoodie.errortable.write.class", HoodieConfig.class.getName());
    assertThrows(HoodieException.class, () -> ErrorTableUtils.getErrorTableWriter(new HoodieStreamer.Config(), sparkSession, props, sparkContext, fileSystem));
}

